{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "A closely related steroidal compound (ThH) was reported to have very low oral bioavailability in humans after tablet administration, directly supporting a low-F phenotype for this steroid-like scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Abiraterone acetate, a steroidal drug, has estimated absolute oral bioavailability of less than 10% in humans, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Testosterone, a structurally similar steroid with a polar hydroxyl group, has mean absolute oral bioavailability of 3.6 ± 2.5% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Mometasone, a corticosteroid, has oral bioavailability below 1%, illustrating that steroid scaffolds frequently undergo extensive first-pass metabolism or poor absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Fulvestrant, a steroidal antiestrogen, has low oral bioavailability and presystemic metabolism in animals and humans, supporting a low-F outcome for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Nestorone, a steroidal progestin, has low oral bioavailability due to rapid gastrointestinal and hepatic inactivation.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues are steroidal compounds with measured or reported oral bioavailability well below 20% (e.g., abiraterone <10%, testosterone ~3.6%, mometasone <1%, fulvestrant low). The query shares the neutral lipophilic steroid/phenol scaffold, so low oral bioavailability is strongly supported.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the exact query molecule.",
    "First-pass metabolism and solubility of the query are not experimentally characterized.",
    "The phenol group may undergo conjugation, but its quantitative impact on bioavailability is unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

